855:fn capture_stream_append(
856:    mut reader: impl Read,
857:    path: &Path,
858:    limit: u64,
859:    retained_before: u64,
860:) -> Result<(u64, u64), UniversalExecError> {
861:    let mut file = OpenOptions::new()
862:        .append(true)
863:        .open(path)
864:        .map_err(|error| {
865:            UniversalExecError::new(
866:                UniversalExecErrorCode::IoError,
867:                format!("cannot open {} for append: {error}", path.display()),
868:                None,
869:                false,
870:            )
871:        })?;
872:    let mut retained = 0_u64;
873:    let mut dropped = 0_u64;
874:    let mut buffer = [0_u8; 16 * 1024];
875:    loop {
876:        let read = reader.read(&mut buffer).map_err(|error| {
877:            UniversalExecError::new(
878:                UniversalExecErrorCode::IoError,
879:                format!("cannot read target output: {error}"),
880:                None,
881:                false,
882:            )
883:        })?;
884:        if read == 0 {
885:            break;
886:        }
887:        let remaining = limit.saturating_sub(retained_before.saturating_add(retained)) as usize;
888:        let write_len = read.min(remaining);
889:        if write_len > 0 {
890:            file.write_all(&buffer[..write_len]).map_err(|error| {
891:                UniversalExecError::new(
892:                    UniversalExecErrorCode::IoError,
893:                    format!("cannot persist target output: {error}"),
894:                    None,
895:                    false,
896:                )
897:            })?;
898:            retained = retained.saturating_add(write_len as u64);
899:        }
900:        dropped = dropped.saturating_add((read - write_len) as u64);
901:    }
902:    file.sync_all().map_err(|error| {
903:        UniversalExecError::new(
904:            UniversalExecErrorCode::IoError,
905:            format!("cannot sync target output: {error}"),
906:            None,
907:            false,
908:        )
909:    })?;
910:    Ok((retained, dropped))
911:}
